// Web Mercator, in pixels at zoom 12 around T-Centralen (the baked geometry's frame)
const W12 = 512 * 4096;
const mx = (lon) => (lon + 180) / 360;
const my = (lat) => (1 - Math.log(Math.tan(Math.PI / 4 + lat * Math.PI / 360)) / Math.PI) / 2;
